  state.findMatches = [];
  if (query) {
    let from = 0;
    while (from <= state.content.length - query.length) {
      const found = state.content.indexOf(query, from);
      if (found < 0) break;
      state.findMatches.push(found);
      from = found + Math.max(1, query.length);
    }
  }
  if (!state.findMatches.length) state.findIndex = -1;
  else state.findIndex = clamp(state.findIndex, 0, state.findMatches.length - 1);
  ui.matchState.textContent = !query ? 'No search' : !state.findMatches.length ? 'No matches' : `${state.findIndex + 1} of ${state.findMatches.length}`;
  updateControls();
}

function findNext() {
  updateFindMatches();
  if (!state.findMatches.length) return showMessage(ui.find.value ? 'No matches found.' : 'Enter text to find.');
  const currentEnd = Math.max(...state.ranges.map((range) => ordered(range)[1]));
  let index = state.findMatches.findIndex((position) => position >= currentEnd);
  if (index < 0) index = 0;
  if (state.findIndex === index && ordered(primary())[0] === state.findMatches[index]) index = (index + 1) % state.findMatches.length;
  state.findIndex = index;
  const start = state.findMatches[index];
  state.ranges = [{ anchor: start, head: start + ui.find.value.length, goalColumn: null }];
  ui.matchState.textContent = `${index + 1} of ${state.findMatches.length}`;
  renderOverlaysAndStatus();
  revealPrimary();
  ui.editor.focus();
}

function replaceCurrent() {
  const query = ui.find.value;
  if (!query || !state.findMatches.length) return;
  const [start, end] = ordered(primary());
  if (state.content.slice(start, end) !== query) {
    findNext();
    return;
  }
  applyEdits([{ start, end, text: ui.replaceText.value }]);
  findNext();
}

function replaceAll() {
  const query = ui.find.value;
  if (!query || !state.findMatches.length) return;
  const replacement = ui.replaceText.value;
  const edits = state.findMatches.map((start) => ({ start, end: start + query.length, text: replacement }));
  applyEdits(edits);
  showMessage(`Replaced ${edits.length} match${edits.length === 1 ? '' : 'es'}.`, 'info');
}

function showMessage(text, type = 'error') {
  ui.message.textContent = text;
  ui.message.className = `message${type === 'info' ? ' info' : ''}`;
  ui.message.hidden = false;
}
function clearMessage() { ui.message.hidden = true; }

async function request(url, options) {
  const response = await fetch(url, options);
  let data;
  try { data = await response.json(); } catch { data = { error: `Request failed (${response.status}).` }; }
  if (!response.ok) {
    const error = new Error(data.error || `Request failed (${response.status}).`);
    error.status = response.status;
    error.data = data;
    throw error;
  }
  return data;
}

async function save() {
  if (!isDirty() || state.preview) return;
  clearMessage();
  ui.save.disabled = true;
  ui.save.textContent = 'Saving…';
  try {
    const data = await request(`/api/documents/${encodeURIComponent(state.id)}`, {
      method: 'PUT', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: state.id, title: state.title, content: state.content, baseRevision: state.baseRevision })
    });
    state.baseRevision = data.document.currentRevision;
    state.savedContent = data.document.content;
    state.conflicted = false;
    showMessage(data.unchanged ? 'Already saved; no duplicate revision was created.' : `Saved revision ${state.baseRevision}.`, 'info');
    updateControls();
    if (!ui.historyPanel.hidden) loadHistory();
  } catch (error) {
    if (error.status === 409) state.conflicted = true;
    showMessage(error.status === 409 ? `${error.message} Latest is revision ${error.data.currentRevision}. Reload to view it; your unsaved text remains here.` : error.message);
    updateControls();
  } finally {
    ui.save.textContent = 'Save';
  }
}

async function loadHistory() {
  try {
    const data = await request(`/api/documents/${encodeURIComponent(state.id)}/revisions`);
    const fragment = document.createDocumentFragment();
    data.revisions.forEach((revision) => {
      const item = document.createElement('li');
      item.className = `revision-item${revision.revisionNumber === state.baseRevision ? ' current' : ''}`;
      const row = document.createElement('div');
      row.className = 'revision-row';
      const label = document.createElement('strong');
      label.textContent = `Revision ${revision.revisionNumber}${revision.revisionNumber === state.baseRevision ? ' · current' : ''}`;
      const button = document.createElement('button');
      button.type = 'button';
      button.textContent = 'Preview';
      button.addEventListener('click', () => previewRevision(revision.revisionNumber));
      row.append(label, button);
      const time = document.createElement('div');
      time.className = 'revision-time';
      time.textContent = `${new Date(revision.createdAt).toLocaleString()} · ${revision.contentLength.toLocaleString()} characters`;
      item.append(row, time);
      fragment.append(item);
    });
    ui.revisionList.replaceChildren(fragment);
  } catch (error) { showMessage(error.message); }
}

async function previewRevision(number) {
  if (state.preview) exitPreview(false);
  try {
    const data = await request(`/api/documents/${encodeURIComponent(state.id)}/revisions/${number}`);
    state.prePreview = snapshot();
    state.preview = data.revision;
    state.content = data.revision.content;
    state.ranges = [{ anchor: 0, head: 0, goalColumn: null }];
    rebuildLines();
    render();
    ui.editor.classList.add('previewing');
    ui.previewBanner.hidden = false;
    ui.previewLabel.textContent = `Previewing revision ${number}`;
    updateFindMatches();
  } catch (error) { showMessage(error.message); }
}

function exitPreview(renderEditor = true) {
  if (!state.preview || !state.prePreview) return;
  const previous = state.prePreview;
  state.preview = null;
  state.prePreview = null;
  ui.previewBanner.hidden = true;
  ui.editor.classList.remove('previewing');
  if (renderEditor) restoreSnapshot(previous);
  else {
    state.content = previous.content;
    state.ranges = previous.ranges;
    rebuildLines();
  }
}

function restorePreview() {
  if (!state.preview || !state.prePreview) return;
  const restored = state.preview;
  const before = state.prePreview;
  state.preview = null;
  state.prePreview = null;
  ui.previewBanner.hidden = true;
  ui.editor.classList.remove('previewing');
  state.content = restored.content;
  state.ranges = [{ anchor: 0, head: 0, goalColumn: null }];
  rebuildLines();
  recordEdit(before);
  updateFindMatches();
  render();
  showMessage(`Revision ${restored.revisionNumber} loaded as an unsaved edit. Save to create a new revision.`, 'info');
}

async function initialize() {
  const measure = document.createElement('canvas').getContext('2d');
  measure.font = getComputedStyle(ui.canvas).font;
  state.charWidth = measure.measureText('M').width;
  try {
    const list = await request('/api/documents');
    if (!list.documents.length) throw new Error('No incident report is available.');
    const data = await request(`/api/documents/${encodeURIComponent(list.documents[0].id)}`);
    const documentData = data.document;
    state.id = documentData.id;
    state.title = documentData.title;
    state.content = documentData.content;
    state.savedContent = documentData.content;
    state.baseRevision = documentData.currentRevision;
    state.ranges = [{ anchor: 0, head: 0, goalColumn: null }];
    ui.title.textContent = state.title;
    document.title = `${state.title} · PatchPad`;
    rebuildLines();
    render();
    updateFindMatches();
  } catch (error) {
    showMessage(`PatchPad could not start: ${error.message}`);
    ui.saveState.textContent = 'Unavailable';
  }
}

ui.editor.addEventListener('keydown', keyDown);
ui.editor.addEventListener('pointerdown', pointerDown);
ui.editor.addEventListener('focus', () => ui.editor.classList.add('focused'));
ui.editor.addEventListener('blur', () => ui.editor.classList.remove('focused'));
document.addEventListener('pointermove', pointerMove);
document.addEventListener('pointerup', pointerUp);
ui.editor.addEventListener('copy', (event) => {
  const text = selectedText();
  if (!text) return;
  event.preventDefault();
  event.clipboardData.setData('text/plain', text);
});
ui.editor.addEventListener('cut', (event) => {
  const text = selectedText();
  if (!text || state.preview) return;
  event.preventDefault();
  event.clipboardData.setData('text/plain', text);
  replaceSelections('');
});
ui.editor.addEventListener('paste', (event) => {
  if (state.preview) return;
  event.preventDefault();
  replaceSelections(event.clipboardData.getData('text/plain').replace(/\r\n?/g, '\n'));
});
ui.undo.addEventListener('click', () => { undo(); ui.editor.focus(); });
ui.redo.addEventListener('click', () => { redo(); ui.editor.focus(); });
ui.save.addEventListener('click', save);
ui.find.addEventListener('input', () => { state.findIndex = -1; updateFindMatches(); });
ui.find.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); findNext(); } });
ui.findNext.addEventListener('click', findNext);
ui.replace.addEventListener('click', replaceCurrent);
ui.replaceAll.addEventListener('click', replaceAll);
ui.historyButton.addEventListener('click', () => {
  ui.historyPanel.hidden = !ui.historyPanel.hidden;
  ui.historyButton.setAttribute('aria-expanded', String(!ui.historyPanel.hidden));
  if (!ui.historyPanel.hidden) loadHistory();
});
ui.closeHistory.addEventListener('click', () => {
  ui.historyPanel.hidden = true;
  ui.historyButton.setAttribute('aria-expanded', 'false');
});
ui.restorePreview.addEventListener('click', restorePreview);
ui.exitPreview.addEventListener('click', () => exitPreview());
window.addEventListener('resize', () => render());
window.addEventListener('beforeunload', (event) => {
  if (isDirty()) { event.preventDefault(); event.returnValue = ''; }
});

initialize();
